(function () {
  var p = (pol && pol.data) ? pol.data : {};
  var policyId = String((trg && trg.policy_id) || '');
  if (!policyId) { throw new Error('renewal-dispatch: the timer payload carries no policy_id'); }
  return {
    policy_id: policyId,
    // The renewal is found the same way flow 6 wrote it: folder = the expiring
    // policy id, origin = publisher-renewal. Both are exact keyword matches, and
    // this survives a regeneration because it never depends on the reference string.
    renewal_filter: JSON.stringify({ conditions: [
      { field: 'folder', keyword: policyId },
      { field: 'origin', keyword: 'publisher-renewal' }] }),
    broker_filter: JSON.stringify({ conditions: [
      { field: 'broker_id', keyword: String(p.broker_id || '') || '__no_broker__' }] }),
    now: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();

(function () {
  var rows = (resp && resp.data && resp.data.results) ? resp.data.results : [];
  var seen = {}, list = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r || !r.id || seen[r.id]) continue;
    seen[r.id] = 1; list.push(r);
  }
  // The newest renewal wins: a regeneration supersedes the one before it.
  var latest = null;
  for (var j = 0; j < list.length; j++) {
    if (!latest) { latest = list[j]; continue; }
    if (String((list[j].data || {}).received_at || '') > String((latest.data || {}).received_at || '')) latest = list[j];
  }
  var d = latest ? (latest.data || {}) : {};
  return {
    found: !!latest,
    submission_id: latest ? String(latest.id) : '',
    quote_id: String(d.quote_id || ''),
    quote_reference: String(d.quote_reference || ''),
    policyholder_name: String(d.gen_policyholder_name || ''),
    occupation: String(d.gen_occupation || ''),
    renewal_count: list.length,
    decision_filter: JSON.stringify({ conditions: [
      { field: 'submission_id', keyword: latest ? String(latest.id) : '__none__' }] })
  };
})();

(function () {
  function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
  var p = (pol && pol.data) ? pol.data : {};
  var rows = (dec && dec.data && dec.data.results) ? dec.data.results : [];
  var seen = {}, list = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r || !r.id || seen[r.id]) continue;
    seen[r.id] = 1; list.push(r);
  }
  // decision_seq is THE ordering key, never decided_at.
  var target = null;
  for (var j = 0; j < list.length; j++) {
    if (!target) { target = list[j]; continue; }
    if (Number((list[j].data || {}).decision_seq || 0) > Number((target.data || {}).decision_seq || 0)) target = list[j];
  }
  var td = target ? (target.data || {}) : {};

  var brows = (brk && brk.data && brk.data.results) ? brk.data.results : [];
  var to = '', toName = '';
  for (var b = 0; b < brows.length; b++) {
    var bd = brows[b].data || {};
    if (bd.primary_contact_email) { to = String(bd.primary_contact_email); toName = String(bd.brokerage_name || bd.primary_contact_name || ''); break; }
  }
  if (!to) { to = String(fallback || ''); toName = 'Antipodean Operations'; }

  var already = !!(td.issued_document_refs && td.issued_document_refs.length);
  var mta = String(p.mta_state || 'none');
  var reasons = [];
  if (String(p.policy_status || '') !== 'ACTIVE') reasons.push('policy_status_is_' + (String(p.policy_status || '') || 'absent'));
  if (String(p.auto_renewal_eligible || '') !== 'true') reasons.push('auto_renewal_eligible_is_' + (String(p.auto_renewal_eligible || '') || 'absent'));
  if (!sub || !sub.found) reasons.push('no_renewal_generated_at_t100');
  if (sub && sub.found && !target) reasons.push('renewal_not_yet_evaluated');
  // spec 4.6.3: an MTA in progress or referred marks the renewal Pending
  // Expiring Endorsement and queues it for MANUAL review, so nothing is
  // dispatched to the broker while one is open.
  if (!(mta === 'none' || mta === '')) reasons.push('mta_state_is_' + mta);
  // Only a clean ACCEPT is dispatched. A REFER is with an underwriter and a
  // DECLINE is not an offer; dispatching either would be a lie to the broker.
  if (target && String(td.outcome || '') !== 'ACCEPT') reasons.push('renewal_outcome_is_' + (String(td.outcome || '') || 'absent'));
  if (target && String(td.decision_status || '') !== 'OPEN') reasons.push('renewal_decision_status_is_' + (String(td.decision_status || '') || 'absent'));
  // Idempotency without a new schema field: issued_document_refs on the renewal
  // decision IS the dispatch record. Non-empty means the invitation went out.
  if (already) reasons.push('already_dispatched');

  return {
    should_dispatch: reasons.length === 0,
    skip_reasons: reasons,
    policy_id: String((trg && trg.policy_id) || ''),
    policy_number: String(p.policy_number || ''),
    expiration_date: String(p.expiration_date || ''),
    renewal_submission_id: sub ? String(sub.submission_id || '') : '',
    renewal_quote_id: sub ? String(sub.quote_id || '') : '',
    renewal_quote_reference: sub ? String(sub.quote_reference || '') : '',
    renewal_decision_id: target ? String(target.id) : '',
    outcome: String(td.outcome || ''),
    total_payable: Number(td.total_payable || 0),
    total_payable_text: (Number(td.total_payable || 0)).toFixed(2),
    quote_validity_expiry: String(td.quote_validity_expiry || ''),
    broker_reasons: td.broker_reasons || [],
    policyholder_name: sub ? String(sub.policyholder_name || '') : '',
    occupation: sub ? String(sub.occupation || '') : '',
    notice_to: to,
    notice_to_name: toName,
    dispatched_at: iso(new Date())
  };
})();

(function () {
  // The generator's reply shape is not guaranteed, so the object key is read
  // where it is offered and DERIVED from the template's own output config
  // otherwise. Both are recorded, and the derived one is marked as derived
  // rather than passed off as observed.
  function firstKey(o) {
    if (!o || typeof o !== 'object') return '';
    if (typeof o.key === 'string') return o.key;
    if (typeof o.object_key === 'string') return o.object_key;
    if (o.output && typeof o.output.key === 'string') return o.output.key;
    return '';
  }
  var rows = [];
  if (gen && gen.data) { rows = Array.isArray(gen.data) ? gen.data : [gen.data]; }
  else if (Array.isArray(gen)) { rows = gen; }
  else if (gen) { rows = [gen]; }
  var key = '';
  var errors = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i] || {};
    if (r.errors && r.errors.length) { errors = errors.concat(r.errors); }
    if (!key) key = firstKey(r);
  }
  var derived = false;
  if (!key) { key = 'antipodean.quotes.quotation-schedule-' + String(ref || '') + '.pdf'; derived = true; }
  if (errors.length) { throw new Error('renewal-dispatch: tpl_quotation_schedule failed: ' + JSON.stringify(errors)); }
  return {
    object_key: key,
    object_key_derived: derived,
    issued_document_refs: [{
      document_type: 'quotation_schedule',
      template_id: 'tpl_quotation_schedule',
      object_key: key
    }]
  };
})();
